```python
"""JSON-backed persistence layer for the warehouse inventory system."""
import json
import os
import tempfile

from models import Product, Location, StockLevel, Movement


class JsonStore:
    """Loads/saves the on-disk JSON document and provides typed accessors.

    The on-disk format is exactly:
        {"products": [Product dicts],
         "locations": [Location dicts],
         "stock": [StockLevel dicts],
         "movements": [Movement dicts]}
    """

    def __init__(self, path: str):
        self.path = path

    # ---------- persistence ----------

    def load(self) -> dict:
        """Load the raw JSON document from disk (or an empty document)."""
        if not os.path.exists(self.path):
            return {"products": [], "locations": [], "stock": [], "movements": []}
        with open(self.path, "r", encoding="utf-8") as f:
            data = json.load(f)
        # Guarantee all four lists exist, in the canonical shape.
        for key in ("products", "locations", "stock", "movements"):
            if key not in data or not isinstance(data[key], list):
                data[key] = []
        return data

    def save(self, data: dict) -> None:
        """Atomically persist the document: write to a temp file, os.replace."""
        tmp_fd, tmp_path = tempfile.mkstemp(
            dir=os.path.dirname(os.path.abspath(self.path)) or ".",
            prefix=".warehouse-",
            suffix=".tmp",
        )
        try:
            with os.fdopen(tmp_fd, "w", encoding="utf-8") as f:
                json.dump(data, f, indent=2)
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp_path, self.path)
        except BaseException:
            if os.path.exists(tmp_path):
                os.unlink(tmp_path)
            raise

    # ---------- typed accessors ----------

    def get_product(self, sku: str) -> Product:
        for d in self.load()["products"]:
            if d.get("sku") == sku:
                return Product.from_dict(d)
        raise KeyError(f"unknown product sku: {sku!r}")

    def get_location(self, code: str) -> Location:
        for d in self.load()["locations"]:
            if d.get("code") == code:
                return Location.from_dict(d)
        raise KeyError(f"unknown location code: {code!r}")

    def stock_at(self, sku: str, code: str) -> int:
        for d in self.load()["stock"]:
            if d.get("sku") == sku and d.get("location_code") == code:
                return int(d.get("quantity", 0))
        return 0

    def set_stock(self, sku: str, code: str, qty: int) -> None:
        """Set the stock level for (sku, code). Creates the row if absent.

        Raises KeyError if the sku or location is unknown.
        """
        self.get_product(sku)      # KeyError if unknown
        self.get_location(code)    # KeyError if unknown
        data = self.load()
        for d in data["stock"]:
            if d.get("sku") == sku and d.get("location_code") == code:
                d["quantity"] = int(qty)
                break
        else:
            data["stock"].append(StockLevel(sku, code, int(qty)).to_dict())
        self.save(data)

    def append_movement(self, m: Movement) -> None:
        self.get_product(m.sku)    # KeyError if unknown sku
        if m.src is not None:
            self.get_location(m.src)
        if m.dst is not None:
            self.get_location(m.dst)
        data = self.load()
        data["movements"].append(m.to_dict())
        self.save(data)
