### rules.py
```python
"""Business rules for the warehouse inventory system."""
import time
from typing import Optional

from models import Movement
from storage import JsonStore


class InsufficientStock(Exception):
    pass


class CapacityExceeded(Exception):
    pass


class DuplicateRef(Exception):
    pass


class Inventory:
    """Applies inventory rules on top of a JsonStore.

    Every successful operation appends exactly one Movement and persists.
    A failing operation (bad qty, unknown sku/location, duplicate ref,
    insufficient stock, capacity exceeded) changes nothing on disk.
    """

    def __init__(self, store: JsonStore):
        self.store = store

    # ---------- helpers ----------

    def _now(self) -> int:
        return int(time.time())

    def _check_qty(self, qty: int) -> None:
        if not isinstance(qty, int) or isinstance(qty, bool) or qty <= 0:
            raise ValueError("qty must be a positive integer")

    def _ref_exists(self, ref: str) -> bool:
        return any(m.get("ref") == ref for m in self.store.load()["movements"])

    def _total_on_hand(self, sku: str, data: dict) -> int:
        return sum(
            int(d.get("quantity", 0))
            for d in data["stock"]
            if d.get("sku") == sku
        )

    def _used_capacity(self, code: str, data: dict) -> int:
        return sum(
            int(d.get("quantity", 0))
            for d in data["stock"]
            if d.get("location_code") == code
        )

    def _apply(self, sku: str, code: str, delta: int, data: dict) -> None:
        """Apply `delta` to (sku, code) within the working document."""
        for d in data["stock"]:
            if d.get("sku") == sku and d.get("location_code") == code:
                d["quantity"] = int(d.get("quantity", 0)) + delta
                break
        else:
            data["stock"].append({"sku": sku, "location_code": code, "quantity": delta})

    def _commit(self, data: dict, movement: Movement) -> None:
        data["movements"].append(movement.to_dict())
        self.store.save(data)

    # ---------- operations ----------

    def receive(self, sku: str, qty: int, dst: str, ref: str) -> Movement:
        self._check_qty(qty)
        if self._ref_exists(ref):
            raise DuplicateRef(f"duplicate ref: {ref!r}")
        product = self.store.get_product(sku)      # KeyError if unknown
        location = self.store.get_location(dst)    # KeyError if unknown

        data = self.store.load()
        if self._used_capacity(dst, data) + qty > location.capacity:
            raise CapacityExceeded(
                f"receive {qty} to {dst!r} exceeds capacity {location.capacity}"
            )

        self._apply(sku, dst, qty, data)
        mv = Movement("receive", sku, qty, None, dst, self._now(), ref)
        self._commit(data, mv)
        return mv

    def ship(self, sku: str, qty: int, src: str, ref: str) -> Movement:
        self._check_qty(qty)
        if self._ref_exists(ref):
            raise DuplicateRef(f"duplicate ref: {ref!r}")
        self.store.get_product(sku)      # KeyError if unknown
        self.store.get_location(src)     # KeyError if unknown

        data = self.store.load()
        if self.store.stock_at(sku, src) < qty:
            raise InsufficientStock(
                f"ship {qty} from {src!r} but only "
                f"{self.store.stock_at(sku, src)} on hand"
            )

        self._apply(sku, src, -qty, data)
        mv = Movement("ship", sku, qty, src, None, self._now(), ref)
        self._commit(data, mv)
        return mv

    def transfer(self, sku: str, qty: int, src: str, dst: str, ref: str) -> Movement:
        self._check_qty(qty)
        if self._ref_exists(ref):
            raise DuplicateRef(f"duplicate ref: {ref!r}")
        self.store.get_product(sku)      # KeyError if unknown
        self.store.get_location(src)     # KeyError if unknown
        self.store.get_location(dst)     # KeyError if unknown

        data = self.store.load()
        if self.store.stock_at(sku, src) < qty:
            raise InsufficientStock(
                f"transfer {qty} from {src!r} but only "
                f"{self.store.stock_at(sku, src)} on hand"
            )
        if self._used_capacity(dst, data) + qty > location_capacity(dst, data):
            raise CapacityExceeded(
                f"transfer {qty} to {dst!r} exceeds capacity"
            )

        self._apply(sku, src, -qty, data)
        self._apply(sku, dst, qty, data)
        mv = Movement("transfer", sku, qty, src, dst, self._now(), ref)
        self._commit(data, mv)
        return mv

    def adjust(self, sku: str, qty_delta: int, loc: str, ref: str) -> Movement:
        if not isinstance(qty_delta, int) or isinstance(qty_delta, bool) or qty_delta == 0:
            raise ValueError("qty_delta must be a non-zero integer")
        if self._ref_exists(ref):
            raise DuplicateRef(f"duplicate ref: {ref!r}")
        self.store.get_product(sku)      # KeyError if unknown
        location = self.store.get_location(loc)  # KeyError if unknown

        data = self.store.load()
        new_qty = self.store.stock_at(sku, loc) + qty_delta
        if new_qty < 0:
            raise InsufficientStock(
                f"adjust {qty_delta:+d} at {loc!r} would go negative "
                f"(currently {self.store.stock_at(sku, loc)})"
            )
        if self._used_capacity(loc, data) + qty_delta > location.capacity:
            raise CapacityExceeded(
                f"adjust {qty_delta:+d} at {loc!r} exceeds capacity {location.capacity}"
            )

        self._apply(sku, loc, qty_delta, data)
        mv = Movement("adjust", sku, qty_delta, loc, None, self._now(), ref)
        self._commit(data, mv)
        return mv

    # ---------- queries ----------

    def total_on_hand(self, sku: str) -> int:
        self.store.get_product(sku)  # KeyError if unknown
        return self._total_on_hand(sku, self.store.load())

    def below_reorder(self) -> list:
        data = self.store.load()
        out = []
        for p in data["products"]:
            if self._total_on_hand(p["sku"], data) < int(p["reorder_point"]):
                out.append(p["sku"])
        return out

    def valuation(self) -> float:
        data = self.store.load()
        costs = {p["sku"]: float(p["unit_cost"]) for p in data["products"]}
        total = 0.0
        for d in data["stock"]:
            total += int(d.get("quantity", 0)) * costs.get(d.get("sku"), 0.0)
        return total

    def ledger(self, sku: str) -> list:
        self.store.get_product(sku)  # KeyError if unknown
        moves = [Movement.from_dict(d) for d in self.store.load()["movements"]]
        moves = [m for m in moves if m.sku == sku]
        moves.sort(key=lambda m: m.ts)
        return moves
