"""Command-line interface for the warehouse inventory system."""
import argparse
import json
import sys

from rules import Inventory, InsufficientStock, CapacityExceeded, DuplicateRef
from storage import JsonStore


def _build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(prog="warehouse", description="Warehouse inventory CLI")
    p.add_argument("--db", required=True, help="path to the JSON store file")
    sub = p.add_subparsers(dest="command", required=True)

    def add_common(sp):
        sp.add_argument("sku")
        sp.add_argument("qty", type=int)
        sp.add_argument("--ref", required=True)

    sp = sub.add_parser("receive", help="receive stock into a location")
    add_common(sp)
    sp.add_argument("--dst", required=True)

    sp = sub.add_parser("ship", help="ship stock from a location")
    add_common(sp)
    sp.add_argument("--src", required=True)

    sp = sub.add_parser("transfer", help="transfer stock between locations")
    add_common(sp)
    sp.add_argument("--src", required=True)
    sp.add_argument("--dst", required=True)

    sp = sub.add_parser("adjust", help="adjust stock by a delta at a location")
    sp.add_argument("sku")
    sp.add_argument("qty_delta", type=int)
    sp.add_argument("--loc", required=True)
    sp.add_argument("--ref", required=True)

    sub.add_parser("report", help="valuation, below_reorder, total_units")
    return p


def main(argv=None) -> int:
    args = _build_parser().parse_args(argv)
    inv = Inventory(JsonStore(args.db))

    try:
        if args.command == "receive":
            mv = inv.receive(args.sku, args.qty, args.dst, args.ref)
            result = {"ok": True, "movement": mv.to_dict()}
        elif args.command == "ship":
            mv = inv.ship(args.sku, args.qty, args.src, args.ref)
            result = {"ok": True, "movement": mv.to_dict()}
        elif args.command == "transfer":
            mv = inv.transfer(args.sku, args.qty, args.src, args.dst, args.ref)
            result = {"ok": True, "movement": mv.to_dict()}
        elif args.command == "adjust":
            mv = inv.adjust(args.sku, args.qty_delta, args.loc, args.ref)
            result = {"ok": True, "movement": mv.to_dict()}
        elif args.command == "report":
            result = {
                "ok": True,
                "valuation": inv.valuation(),
                "below_reorder": inv.below_reorder(),
                "total_units": sum(
                    int(d.get("quantity", 0))
                    for d in inv.store.load()["stock"]
                ),
            }
        else:  # pragma: no cover
            raise AssertionError("unreachable")
    except (ValueError, KeyError, InsufficientStock, CapacityExceeded, DuplicateRef) as e:
        result = {"ok": False, "error": str(e)}

    print(json.dumps(result))
    return 0 if result.get("ok") else 1


if __name__ == "__main__":
    sys.exit(main())
