"""Unit tests for the warehouse inventory system. Run: python -m unittest tests"""
import json
import os
import tempfile
import unittest

from models import Product, Location, StockLevel, Movement
from rules import (
    Inventory,
    InsufficientStock,
    CapacityExceeded,
    DuplicateRef,
)
from storage import JsonStore


def make_doc():
    return {
        "products": [
            {"sku": "SKU1", "name": "Widget", "unit_cost": 2.5, "reorder_point": 10},
            {"sku": "SKU2", "name": "Gadget", "unit_cost": 4.0, "reorder_point": 5},
        ],
        "locations": [
            {"code": "A", "capacity": 100},
            {"code": "B", "capacity": 50},
        ],
        "stock": [
            {"sku": "SKU1", "location_code": "A", "quantity": 8},
            {"sku": "SKU2", "location_code": "B", "quantity": 6},
        ],
        "movements": [],
    }


class Base(unittest.TestCase):
    def setUp(self):
        fd, self.path = tempfile.mkstemp(suffix=".json")
        os.close(fd)
        with open(self.path, "w", encoding="utf-8") as f:
            json.dump(make_doc(), f)
        self.store = JsonStore(self.path)
        self.inv = Inventory(self.store)

    def tearDown(self):
        if os.path.exists(self.path):
            os.unlink(self.path)


class TestStorage(Base):
    def test_load_returns_canonical_shape(self):
        doc = self.store.load()
        self.assertEqual(set(doc.keys()), {"products", "locations", "stock", "movements"})
        self.assertEqual(len(doc["products"]), 2)
        self.assertEqual(len(doc["locations"]), 2)
        self.assertEqual(len(doc["stock"]), 2)
        self.assertEqual(len(doc["movements"]), 0)

    def test_get_product_and_location(self):
        p = self.store.get_product("SKU1")
        self.assertEqual(p.name, "Widget")
        self.assertEqual(p.unit_cost, 2.5)
        loc = self.store.get_location("B")
        self.assertEqual(loc.capacity, 50)
        with self.assertRaises(KeyError):
            self.store.get_product("NOPE")
        with self.assertRaises(KeyError):
            self.store.get_location("ZZZ")

    def test_stock_at_and_set_stock(self):
        self.assertEqual(self.store.stock_at("SKU1", "A"), 8)
        self.assertEqual(self.store.stock_at("SKU1", "B"), 0)  # absent -> 0
        self.store.set_stock("SKU2", "A", 3)
        self.assertEqual(self.store.stock_at("SKU2", "A"), 3)
        with self.assertRaises(KeyError):
            self.store.set_stock("NOPE", "A", 1)
        with self.assertRaises(KeyError):
            self.store.set_stock("SKU1", "ZZZ", 1)

    def test_append_movement_and_persist(self):
        mv = Movement("receive", "SKU1", 5, None, "A", 123, "ref-x")
        self.store.append_movement(mv)
        doc = self.store.load()
        self.assertEqual(len(doc["movements"]), 1)
        self.assertEqual(doc["movements"][0]["ref"], "ref-x")
        # Round-trip through from_dict/to_dict
        again = Movement.from_dict(doc["movements"][0])
        self.assertEqual(again.to_dict(), mv.to_dict())
        with self.assertRaises(KeyError):
            self.store.append_movement(
                Movement("receive", "NOPE", 1, None, "A", 1, "ref-y")
            )

    def test_atomic_save_leaves_no_temp_files(self):
        self.store.set_stock("SKU1", "A", 42)
        leftovers = [
            fn for fn in os.listdir(os.path.dirname(self.path))
            if fn.startswith(".warehouse-") and fn.endswith(".tmp")
        ]
        self.assertEqual(leftovers, [])
        with open(self.path, "r", encoding="utf-8") as f:
            doc = json.load(f)
        self.assertEqual(doc["stock"][0]["quantity"], 42)


class TestRulesReceiveShip(Base):
    def test_receive_increases_stock_and_records_movement(self):
        mv = self.inv.receive("SKU1", 5, "A", "r1")
        self.assertEqual(self.store.stock_at("SKU1", "A"), 13)
        self.assertEqual(mv.kind, "receive")
        self.assertEqual(mv.dst, "A")
        self.assertEqual(mv.src, None)
        led = self.inv.ledger("SKU1")
        self.assertEqual(len(led), 1)
        self.assertEqual(led[0].ref, "r1")

    def test_receive_unknown_sku_or_location_raises_keyerror(self):
        with self.assertRaises(KeyError):
            self.inv.receive("NOPE", 5, "A", "r1")
        with self.assertRaises(KeyError):
            self.inv.receive("SKU1", 5, "ZZZ", "r2")
        self.assertEqual(self.store.load()["movements"], [])  # nothing recorded

    def test_receive_nonpositive_qty_raises_valueerror(self):
        for bad in (0, -3):
            with self.assertRaises(ValueError):
                self.inv.receive("SKU1", bad, "A", "r-bad")
        self.assertEqual(self.store.load()["movements"], [])

    def test_receive_capacity_exceeded(self):
        # Location B has capacity 50 and currently 0 of anything relevant;
        # put 48 units of SKU2 in B, receiving 5 more of SKU1 exceeds 50.
        self.store.set_stock("SKU2", "B", 48)
        with self.assertRaises(CapacityExceeded):
            self.inv.receive("SKU1", 5, "B", "r-cap")
        self.assertEqual(self.store.stock_at("SKU1", "B"), 0)
        # Exactly filling capacity is allowed.
        mv = self.inv.receive("SKU1", 2, "B", "r-cap2")
        self.assertEqual(self.store.stock_at("SKU1", "B"), 2)

    def test_ship_decreases_stock_and_records_movement(self):
        mv = self.inv.ship("SKU1", 3, "A", "s1")
        self.assertEqual(self.store.stock_at("SKU1", "A"), 5)
        self.assertEqual(mv.kind, "ship")
        self.assertEqual(mv.src, "A")
        self.assertEqual(mv.dst, None)

    def test_ship_insufficient_stock(self):
        with self.assertRaises(InsufficientStock):
            self.inv.ship("SKU1", 9, "A", "s2")  # only 8 on hand
        self.assertEqual(self.store.stock_at("SKU1", "A"), 8)
        self.assertEqual(self.store.load()["movements"], [])

    def test_ship_unknown_sku_or_location(self):
        with self.assertRaises(KeyError):
            self.inv.ship("NOPE", 1, "A", "s3")
        with self.assertRaises(KeyError):
            self.inv.ship("SKU1", 1, "ZZZ", "s4")


class TestRulesTransferAdjust(Base):
    def test_transfer_moves_stock_and_records_one_movement(self):
        mv = self.inv.transfer("SKU1", 4, "A", "B", "t1")
        self.assertEqual(self.store.stock_at("SKU1", "A"), 4)
        self.assertEqual(self.store.stock_at("SKU1", "B"), 4)
        self.assertEqual(mv.kind, "transfer")
        self.assertEqual((mv.src, mv.dst), ("A", "B"))
        self.assertEqual(len(self.inv.ledger("SKU1")), 1)

    def test_transfer_insufficient_stock(self):
        with self.assertRaises(InsufficientStock):
            self.inv.transfer("SKU1", 20, "A", "B", "t2")
        self.assertEqual(self.store.stock_at("SKU1", "A"), 8)
        self.assertEqual(self.store.stock_at("SKU1", "B"), 0)

    def test_transfer_capacity_exceeded_at_dst(self):
        # Fill B with 49 units; transferring 2 more of SKU1 exceeds 50.
        self.store.set_stock("SKU2", "B", 49)
        with self.assertRaises(CapacityExceeded):
            self.inv.transfer("SKU1", 2, "A", "B", "t3")
        self.assertEqual(self.store.stock_at("SKU1", "A"), 8)
        self.assertEqual(self.store.stock_at("SKU1", "B"), 0)

    def test_transfer_unknown_locations(self):
        with self.assertRaises(KeyError):
            self.inv.transfer("SKU1", 1, "A", "ZZZ", "t4")
        with self.assertRaises(KeyError):
            self.inv.transfer("SKU1", 1, "ZZZ", "A", "t5")

    def test_adjust_positive_and_negative(self):
        self.inv.adjust("SKU1", +2, "A", "a1")
        self.assertEqual(self.store.stock_at("SKU1", "A"), 10)
        self.inv.adjust("SKU1", -3, "A", "a2")
        self.assertEqual(self.store.stock_at("SKU1", "A"), 7)
        kinds = [m.kind for m in self.inv.ledger("SKU1")]
        self.assertEqual(kinds, ["adjust", "adjust"])

    def test_adjust_zero_delta_raises_valueerror(self):
        with self.assertRaises(ValueError):
            self.inv.adjust("SKU1", 0, "A", "a3")
        self.assertEqual(self.store.load()["movements"], [])

    def test_adjust_would_go_negative_raises_insufficient(self):
        with self.assertRaises(InsufficientStock):
            self.inv.adjust("SKU1", -9, "A", "a4")  # only 8 on hand
        self.assertEqual(self.store.stock_at("SKU1", "A"), 8)

    def test_adjust_capacity_exceeded(self):
        with self.assertRaises(CapacityExceeded):
            self.inv.adjust("SKU1", +93, "A", "a5")  # 8 + 93 > 100
        self.assertEqual(self.store.stock_at("SKU1", "A"), 8)


class TestRulesMisc(Base):
    def test_duplicate_ref_blocked_and_changes_nothing(self):
        self.inv.receive("SKU1", 2, "A", "dup")
        before = self.store.load()
        with self.assertRaises(DuplicateRef):
            self.inv.receive("SKU1", 2, "A", "dup")
        self.assertEqual(self.store.load(), before)
        with self.assertRaises(DuplicateRef):
            self.inv.ship("SKU1", 1, "A", "dup")
        with self.assertRaises(DuplicateRef):
            self.inv.transfer("SKU1", 1, "A", "B", "dup")
        with self.assertRaises(DuplicateRef):
            self.inv.adjust("SKU1", 1, "A", "dup")
        self.assertEqual(len(self.store.load()["movements"]), 1)

    def test_total_on_hand_sums_locations(self):
        self.inv.transfer("SKU1", 3, "A", "B", "x1")
        self.assertEqual(self.inv.total_on_hand("SKU1"), 8)
        self.inv.ship("SKU1", 2, "A", "x2")
        self.assertEqual(self.inv.total_on_hand("SKU1"), 6)
        with self.assertRaises(KeyError):
            self.inv.total_on_hand("NOPE")

    def test_below_reorder(self):
        # SKU1: 8 on hand, reorder_point 10 -> below. SKU2: 6, reorder 5 -> ok.
        self.assertEqual(self.inv.below_reorder(), ["SKU1"])
        self.inv.receive("SKU1", 5, "A", "br1")  # 13 on hand now
        self.assertEqual(self.inv.below_reorder(), [])

    def test_valuation(self):
        # SKU1: 8 * 2.5 = 20.0 ; SKU2: 6 * 4.0 = 24.0 -> 44.0
        self.assertAlmostEqual(self.inv.valuation(), 44.0)
        self.inv.ship("SKU2", 6, "B", "v1")  # remove all SKU2
        self.assertAlmostEqual(self.inv.valuation(), 20.0)

    def test_ledger_sorted_by_ts(self):
        self.inv.receive("SKU1", 1, "A", "l1")
        self.inv.ship("SKU1", 1, "A", "l2")
        self.inv.receive("SKU1", 1, "A", "l3")
        led = self.inv.ledger("SKU1")
        self.assertEqual([m.ref for m in led], ["l1", "l2", "l3"])
        self.assertTrue(all(a.ts <= b.ts for a, b in zip(led, led[1:])))
        # ledger for other sku is empty
        self.assertEqual(self.inv.ledger("SKU2"), [])


