class TestCLI(unittest.TestCase):
    def setUp(self):
        fd, self.path = tempfile.mkstemp(suffix=".json")
        os.close(fd)
        with open(self.path, "w", encoding="utf-8") as f:
            json.dump(make_doc(), f)

    def tearDown(self):
        if os.path.exists(self.path):
            os.unlink(self.path)

    def _run(self, argv):
        import io
        import contextlib
        from cli import main
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            code = main(argv)
        return code, json.loads(buf.getvalue())

    def test_cli_receive_and_report(self):
        code, out = self._run(["--db", self.path, "receive", "SKU1", "5",
                               "--dst", "A", "--ref", "c1"])
        self.assertEqual(code, 0)
        self.assertTrue(out["ok"])
        code, out = self._run(["--db", self.path, "report"])
        self.assertEqual(code, 0)
        self.assertEqual(out["total_units"], 19)  # 8+5 + 6
        self.assertAlmostEqual(out["valuation"], 56.5)  # 13*2.5 + 6*4
        self.assertEqual(out["below_reorder"], [])

    def test_cli_error_line_is_json(self):
        code, out = self._run(["--db", self.path, "ship", "SKU1", "999",
                               "--src", "A", "--ref", "c2"])
        self.assertEqual(code, 1)
        self.assertFalse(out["ok"])
        self.assertIn("error", out)


if __name__ == "__main__":
    unittest.main()
```

Notes on behavior:
- All four on-disk keys are lists of plain dicts in the exact fixture format; a fixture that writes that JSON directly loads cleanly.
- Saves are atomic (temp file + `os.replace`), and failed operations leave the file byte-identical (rules load a working copy and only save on success).
- `ref` uniqueness is enforced across all movement kinds; duplicates raise `DuplicateRef` with no mutation.
- Capacity is checked as the sum of all skus at the destination location, including the incoming quantity.
- Run tests with `python -m unittest tests` from the directory containing all five files.
